<template><view v-if="active"><WarmDialog :open="!!feedback.dialog" :title="feedback.dialog?.title||''" @close="settleDialog(false)"><view class="feedback-content"><image src="/static/mascot/xiaoshi.png" mode="aspectFit" class="feedback-dog" alt="小时陪着你"/><text class="feedback-message">{{feedback.dialog?.content}}</text></view><view class="feedback-actions"><button v-if="!feedback.dialog?.info" class="secondary feedback-cancel" @click="settleDialog(false)">取消</button><button class="primary feedback-confirm" @click="settleDialog(true)">{{feedback.dialog?.info?'知道啦':'确定'}}</button></view></WarmDialog><view v-if="feedback.toast" class="warm-toast" role="status" aria-live="polite"><image src="/static/illustrations/sun.png" mode="aspectFit"/><text>{{feedback.toast}}</text><button aria-label="关闭提示" @click="feedback.toast=''">×</button></view></view></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import WarmDialog from './WarmDialog.vue';import {feedback,settleDialog} from '../services/feedback';
const active=ref(false);onMounted(()=>active.value=true);onShow(()=>active.value=true);
function hide(){if(active.value)settleDialog(false);active.value=false;}onHide(hide);onUnload(hide);onBeforeUnmount(hide);
</script>
<style scoped>.feedback-content{display:flex;flex-direction:column;align-items:center;padding:10rpx 10rpx 28rpx}.feedback-dog{width:145rpx;height:145rpx;margin-bottom:18rpx}.feedback-message{white-space:pre-wrap;overflow-wrap:anywhere;font-size:28rpx;line-height:1.85;color:#745737;text-align:center}.feedback-actions{display:flex;gap:20rpx;padding:8rpx 0}.feedback-actions button{flex:1;min-width:0}.warm-toast{position:fixed;z-index:800;top:90px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:14rpx;width:max-content;max-width:calc(100vw - 40px);background:#fff4d3;border:2rpx solid #dfbe77;box-shadow:0 8px 30px #72502122;color:#72522c;border-radius:22rpx;padding:18rpx 20rpx;box-sizing:border-box;font-size:25rpx;line-height:1.7}.warm-toast image{width:52rpx;height:52rpx;flex-shrink:0}.warm-toast text{overflow-wrap:anywhere}.warm-toast button{background:transparent;font-size:30rpx;color:#927046;padding:0 8rpx;flex-shrink:0}
</style>
<style scoped>/* #ifdef H5 */@media(min-width:1000px){.feedback-message{font-size:18px}.feedback-dog{width:110px;height:110px}.feedback-actions button{font-size:16px;padding:15px}.warm-toast{font-size:16px;max-width:620px}}/* #endif */</style>
